def AcpiMcfgParser (McfgRaw):
  """Return an MCFG object and its dynamic type; McfgDesc is always an array."""

  import EfiPy2 as EfiPy
  from EfiPy2.MdePkg.IndustryStandard import EFIPY_INDUSTRY_STRUCTURE
  from EfiPy2.MdePkg.IndustryStandard import MemoryMappedConfigurationSpaceAccessTable as McfgTable

  HeaderType = McfgTable.EFI_ACPI_MEMORY_MAPPED_CONFIGURATION_BASE_ADDRESS_TABLE_HEADER
  DescType = McfgTable.EFI_ACPI_MEMORY_MAPPED_ENHANCED_CONFIGURATION_SPACE_BASE_ADDRESS_ALLOCATION_STRUCTURE
  HeaderSize = EfiPy.sizeof (HeaderType)
  DescSize = EfiPy.sizeof (DescType)
  if McfgRaw is None or len (McfgRaw) < HeaderSize:
    raise ValueError ('Missing or truncated ACPI MCFG header.')
  if McfgRaw[:4] != b'MCFG':
    raise ValueError ('Invalid ACPI MCFG signature.')

  Header = HeaderType.from_buffer_copy (McfgRaw)
  TableLength = Header.Header.Length
  if (TableLength > len (McfgRaw) or TableLength < HeaderSize + DescSize or
      (TableLength - HeaderSize) % DescSize):
    raise ValueError ('Invalid ACPI MCFG length or allocation count.')
  if sum (McfgRaw[:TableLength]) & 0xFF:
    raise ValueError ('Invalid ACPI MCFG checksum.')
  DescCount = (TableLength - HeaderSize) // DescSize

  class McfgType (EFIPY_INDUSTRY_STRUCTURE):
    _fields_ = [
      ('Header', HeaderType),
      ('McfgDesc', DescType * DescCount),
    ]

  McfgObj = McfgType.from_buffer_copy (McfgRaw)

  return McfgObj, McfgType

if __name__ == '__main__':

  import sys
  from EfiPy2.Lib.StructDump import DumpStruct
  from EfiPy2.Lib.HexDump import HexDump

  McfgFileName   = sys.argv[4]
  McfgFileHandle = open (McfgFileName, 'rb')
  if McfgFileHandle == None:
    print (f"Open {McfgFileName} error.")
    sys.exit (-1)

  McfgRaw = McfgFileHandle.read()
  McfgObj, McfgType = AcpiMcfgParser (McfgRaw)

  DumpStruct (2, McfgObj, McfgType)
  print ('\n==== ACPI MCFG RAW data ======')
  HexDump (McfgRaw)
